enum ClothingStyle: String, Codable, CaseIterable, Identifiable {
    // Classic & Timeless
    case minimalist = "Minimalist"
    case vintage = "Vintage"
    case retro = "Retro"
    case chic = "Chic"
    case preppy = "Preppy"
    
    // Expressive & Artistic
    case romantic = "Romantic"
    case bohemian = "Bohemian"
    case avantGarde = "Avant Garde"
    case eclectic = "Eclectic"
    
    // Casual & Modern
    case streetwear = "Streetwear"
    case casual = "Casual"
    case sporty = "Sporty"
    case grunge = "Grunge"
    
    // Bold & Vibrant
    case vibrant = "Vibrant"
    case edgy = "Edy"
    case glam = "Glam"
    case cyberpunk = "Cyberpunk"
    
    var id: Self { self }
}
enum ClothingColor: String, Codable, CaseIterable, Identifiable {
    // Blues
    case lightBlue = "Light Blue"
    case royalBlue = "Royal Blue"
    case navyBlue = "Navy Blue"
    
    // Reds & Pinks
    case pastelPink = "Pastel Pink"
    case red = "Red"
    case maroon = "Maroon"
    
    // Greens
    case mintGreen = "Mint Green"
    case emeraldGreen = "Emerald Green"
    case olive = "Olive"
    
    // Yellows & Oranges
    case cream = "Cream"
    case yellow = "Yellow"
    case mustard = "Mustard"
    case peach = "Peach"
    case orange = "Orange"
    case rust = "Rust"
    
    // Purples
    case lavender = "Lavender"
    case purple = "Purple"
    case plum = "Plum"
    
    // Browns & Neutrals
    case tan = "Tan"
    case brown = "Brown"
    case espresso = "Espresso"
    
    // Monochromes
    case white = "White"
    case lightGray = "Light Gray"
    case charcoal = "Charcoal"
    case black = "Black"
    
    var id: Self { self }
}
enum ClothingType: String, Codable, CaseIterable, Identifiable {
    // Upper Body
    case top = "Top"
    case outerwear = "Outerwear"
    
    // Lower Body
    case bottom = "Bottom"
    case skirt = "Skirt"
    
    // Full Body
//    case onePiece = "One Piece"
    
    // Footwear
    case footwear = "Footwear"
    
    // Accessories & Extras
    case accessory = "Accessory"
    
    var id: Self { self }
}

@Model // @model classes can only support basic types, like string and int, but not enums. "String, Codable" have been applied to the enums so that they are read to the class as strings.
class ClothingItem {
//    var image: PhotosPickerItem
    var name: String
    var style: ClothingStyle
    var colour: ClothingColor
    var type: ClothingType
//    var attire: ClothingAttire
    
    init(/*image: PhotosPickerItem, */name: String, style: ClothingStyle, colour: ClothingColor, type: ClothingType/*, attire: ClothingAttire*/) {
//        self.image = image
        self.name = name
        self.style = style
        self.colour = colour
        self.type = type
//        self.attire = attire
    }
    
    var description: String {
        return "(Name: \(name), Style: \(style.rawValue), Colour: \(colour.rawValue))"
    }
}

@Model
class Outfit {
    var top: ClothingItem
    var bottom: ClothingItem
    var accessories: [ClothingItem] = []
    var footwear: ClothingItem
    init(top: ClothingItem, bottom: ClothingItem, accessories: [ClothingItem], footwear: ClothingItem) {
        self.accessories = accessories
        self.footwear = footwear
        self.top = top
        self.bottom = bottom
    }
    
    var description: String {
        return "(Top: \(top.description), Bottom: \(bottom.description), Footwear: \(footwear.description)"
    }
}

func colourDoesClash(colour1: ClothingColor, colour2: ClothingColor) -> Bool {
    
    if colour1 == colour2 {
        return false
    }
    
    switch colour1 {
        case .lightBlue:
            switch colour2 {
            case .red, .orange: return true
            default: return false
            }
        case .royalBlue:
            switch colour2 {
            case .maroon: return true
            default: return false
            }
        case .navyBlue:
            switch colour2 {
            case .black, .espresso: return true
            default: return false
            }
        case .pastelPink:
            switch colour2 {
            case .orange, .yellow: return true
            default: return false
            }
        case .red:
            switch colour2 {
            case .lightBlue, .orange, .purple, .emeraldGreen: return true
            default: return false
            }
        case .maroon:
            switch colour2 {
            case .royalBlue, .rust: return true
            default: return false
            }
        case .mintGreen:
            switch colour2 {
            case .orange: return true
            default: return false
            }
        case .emeraldGreen:
            switch colour2 {
            case .red: return true
            default: return false
            }
        case .olive:
            switch colour2 {
            case .purple: return true
            default: return false
            }
        case .cream:
            switch colour2 {
            case .white: return true
            default: return false
            }
        case .yellow:
            switch colour2 {
            case .pastelPink, .mustard: return true
            default: return false
            }
        case .mustard:
            switch colour2 {
            case .yellow, .purple: return true
            default: return false
            }
        case .orange:
            switch colour2 {
            case .lightBlue, .pastelPink, .red, .mintGreen, .purple: return true
            default: return false
            }
        case .rust:
            switch colour2 {
            case .maroon: return true
            default: return false
            }
        case .purple:
            switch colour2 {
            case .red, .olive, .mustard, .orange: return true
            default: return false
            }
        case .brown:
            switch colour2 {
            case .black: return true
            default: return false
            }
        case .espresso:
            switch colour2 {
            case .navyBlue, .charcoal: return true
            default: return false
            }
        case .white:
            switch colour2 {
            case .cream: return true
            default: return false
            }
        case .charcoal:
            switch colour2 {
            case .espresso: return true
            default: return false
            }
        case .black:
            switch colour2 {
            case .navyBlue, .brown: return true
            default: return false
            }
    default:
        return false
    }
} // mostly generated by AI. i do NOT have time to type allat

func styleDoesClash(style1: ClothingStyle, style2: ClothingStyle) -> Bool {
    
    if style1 == style2 {
        return false
    }
    
    switch style1 {
    case .minimalist:
        switch style2 {
        case .eclectic, .avantGarde, .bohemian: return true
        default: return false
        }
    case .vintage:
        switch style2 {
        case .cyberpunk, .sporty: return true
        default: return false
        }
    case .retro:
        switch style2 {
        case .cyberpunk, .minimalist: return true
        default: return false
        }
    case .chic:
        switch style2 {
        case .grunge, .sporty: return true
        default: return false
        }
    case .preppy:
        switch style2 {
        case .grunge, .cyberpunk, .edgy: return true
        default: return false
        }
    case .romantic:
        switch style2 {
        case .cyberpunk, .grunge, .edgy: return true
        default: return false
        }
    case .bohemian:
        switch style2 {
        case .cyberpunk, .minimalist, .preppy: return true
        default: return false
        }
    case .avantGarde:
        switch style2 {
        case .minimalist, .casual, .preppy: return true
        default: return false
        }
    case .eclectic:
        switch style2 {
        case .minimalist: return true
        default: return false
        }
    case .streetwear:
        switch style2 {
        case .preppy, .romantic: return true
        default: return false
        }
    case .casual:
        switch style2 {
        case .avantGarde, .glam: return true
        default: return false
        }
    case .sporty:
        switch style2 {
        case .glam, .vintage, .romantic: return true
        default: return false
        }
    case .grunge:
        switch style2 {
        case .preppy, .glam, .chic, .romantic: return true
        default: return false
        }
    case .vibrant:
        switch style2 {
        case .minimalist: return true
        default: return false
        }
    case .edgy:
        switch style2 {
        case .preppy, .romantic: return true
        default: return false
        }
    case .glam:
        switch style2 {
        case .grunge, .sporty, .casual: return true
        default: return false
        }
    case .cyberpunk:
        switch style2 {
        case .vintage, .retro, .preppy, .romantic, .bohemian: return true
        default: return false
        }
    }
} // mostly generated by AI. i do NOT have time to type allat

@Generable()
struct OutfitIndex {
    @Guide(description: "The index of the outfit you have chosen.", .range(0...10))
    let index: Int
}

func generateDailyOutfitAI(clothingItems: [ClothingItem], previousOutfits: [Outfit]) async -> Outfit? {
        //    let groupedClothingItems = Dictionary(grouping: clothingItems, by: { $0.type }) // what this line does is create a dictionary of all clothing items grouped by their clothing type.
    
    var tops: [ClothingItem] = []
    var bottoms: [ClothingItem] = []
    var footwear: [ClothingItem] = []
    var misc: [ClothingItem] = []
    
    for clothingItem in clothingItems {
        switch clothingItem.type {
            case .top:      tops.append(clothingItem)
            case .bottom:   bottoms.append(clothingItem)
            case .footwear: footwear.append(clothingItem)
            default:        misc.append(clothingItem)
        }
    }
    
    if tops.isEmpty || bottoms.isEmpty || footwear.isEmpty {
        return nil
    }
    
    let model = SystemLanguageModel.default
    let session = LanguageModelSession()
    var randomOutfitCombinations: [Outfit] = []
    var randomOutfitCombinationStrings: [String] = []
    
    print(model.isAvailable ? "Model is avaliable" : "Model is not avaliable")
    
    if model.isAvailable == true {
        
        for _ in 1...8 {
            let randomOutfit = Outfit(top: tops.randomElement()!, bottom: bottoms.randomElement()!, accessories: [], footwear: footwear.randomElement()!)
            randomOutfitCombinations.append(randomOutfit)
            randomOutfitCombinationStrings.append(randomOutfit.description)
        }
        
        do {
            let prompt = "Here are some outfit choices: \(randomOutfitCombinationStrings). You are a professional outfit designer. Return ONLY a number representing the index (starting from 0) of the outfit that you decide is most fashionable."
            print(prompt)
            
            let response = try await session.respond(to: prompt, generating: OutfitIndex.self)
            
            return randomOutfitCombinations[response.content.index]
        } catch {
            print("failed : \(error)")
        }
        return generateDailyOutfit(clothingItems: clothingItems, previousOutfits: previousOutfits)!
        
    }
    print("Model is not avaliable \(model.availability)")
    return generateDailyOutfit(clothingItems: clothingItems, previousOutfits: previousOutfits)!
}

func generateDailyOutfit(clothingItems: [ClothingItem], previousOutfits: [Outfit]) -> Outfit? {
//    let groupedClothingItems = Dictionary(grouping: clothingItems, by: { $0.type }) // what this line does is create a dictionary of all clothing items grouped by their clothing type.
    
    var tops: [ClothingItem] = []
    var bottoms: [ClothingItem] = []
    var footwear: [ClothingItem] = []
    var misc: [ClothingItem] = []
    
    for clothingItem in clothingItems {
        switch clothingItem.type {
        case .top:      tops.append(clothingItem)
        case .bottom:   bottoms.append(clothingItem)
        case .footwear: footwear.append(clothingItem)
        default:        misc.append(clothingItem)
        }
    }
    
    if tops.isEmpty || bottoms.isEmpty || footwear.isEmpty {
        return nil
    }
        
    var count = 5
    while true {
            
        
        let randomTop = tops.randomElement()!
        let randomBottom = bottoms.randomElement()!
        let randomFootwear = footwear.randomElement()!
        
        if count <= 1 {
            return Outfit(top: randomTop, bottom: randomBottom, accessories: [], footwear: randomFootwear)
        }
        
        if colourDoesClash(colour1: randomTop.colour, colour2: randomBottom.colour) || styleDoesClash(style1: randomTop.style, style2: randomBottom.style) {
            count -= 1
            continue;
        } else {
            return Outfit(top: randomTop, bottom: randomBottom, accessories: [], footwear: randomFootwear)
        }
    }
    
    return nil
        
}

